// P29 A3 (E243): suchbar ist, was die Karte zeigt (Matrix SPEZIFIKATION_PAKET29 §7 V3); Anbieterland bleibt (E129).
const smartHaystack = offer => normalize([
  offer.title, offer.description, offer.provider, offer.focus, humanizeTokens(offer.format, labels.format),
  neutralMissing(readableCodes(offer.duration), "Dauer"), neutralMissing(readableCodes(publicStart(offer)), "Start"),
  placeLabel(offer), placeSearchText(offer), labels.focus[offer.focus], labels.level[offer.level], labels.offerType[offer.offerType]
].join(" "));
